var now = new Date();
var cutoff = new Date(now.getTime() - 365 * 24 * 60 * 60 * 1000); // PRUEBA: 1 año — cambiar a 2 * 60 * 1000 en producción

function pad(n) { return String(n).padStart(2, '0'); }
function toOdoo(d) {
  return d.getUTCFullYear() + '-' + pad(d.getUTCMonth()+1) + '-' + pad(d.getUTCDate()) +
    ' ' + pad(d.getUTCHours()) + ':' + pad(d.getUTCMinutes()) + ':' + pad(d.getUTCSeconds());
}

return [{ json: {
  cutoff: toOdoo(cutoff),
  now_label: now.toLocaleString('es-VE', { timeZone: 'America/Caracas' })
} }];

