var resultado = $('Buscar Sesiones Cerradas Modificadas').first().json.result || [];
var params = $('Calcular Ventana de Tiempo').first().json;

// Filtrar solo sesiones modificadas DESPUÉS de su cierre
var sospechosas = resultado.filter(function(s) {
  if (!s.stop_at || !s.write_date) return false;
  var fechaCierre = new Date(s.stop_at.replace(' ', 'T') + 'Z');
  var fechaModif = new Date(s.write_date.replace(' ', 'T') + 'Z');
  // Tolerancia de 60 segundos para cambios propios del proceso de cierre
  return (fechaModif - fechaCierre) > 60000;
});

if (sospechosas.length === 0) return [];

var filas = '';
sospechosas.forEach(function(s, i) {
  var bg = i % 2 === 0 ? '#ffffff' : '#fff8e1';
  var sesion = s.name || 'N/A';
  var empresa = s.company_id ? s.company_id[1] : 'N/A';
  var punto = s.config_id ? s.config_id[1] : 'N/A';
  var responsable = s.write_uid ? s.write_uid[1] : 'Desconocido';

  var fechaCierre = new Date(s.stop_at.replace(' ', 'T') + 'Z');
  var fechaModif = new Date(s.write_date.replace(' ', 'T') + 'Z');
  var diffMin = Math.round((fechaModif - fechaCierre) / 60000);
  var diffLabel = diffMin >= 60
    ? Math.round(diffMin / 60) + 'h ' + (diffMin % 60) + 'min despu\u00e9s del cierre'
    : diffMin + ' min despu\u00e9s del cierre';

  var saldo = typeof s.cash_register_balance_end_real === 'number'
    ? s.cash_register_balance_end_real.toLocaleString('es-VE', { minimumFractionDigits: 2 })
    : '—';
  var diff = typeof s.cash_register_difference === 'number'
    ? s.cash_register_difference
    : null;
  var diffStyle = diff !== null && diff < 0 ? 'color:#dc3545;font-weight:700;' : diff > 0 ? 'color:#28a745;font-weight:700;' : 'color:#555;';
  var diffText = diff !== null
    ? (diff >= 0 ? '+' : '') + diff.toLocaleString('es-VE', { minimumFractionDigits: 2 })
    : '—';

  var cierreStr = fechaCierre.toLocaleString('es-VE', { timeZone: 'America/Caracas' });
  var modifStr = fechaModif.toLocaleString('es-VE', { timeZone: 'America/Caracas' });

  filas += '<tr style="background:' + bg + '">' +
    '<td style="padding:8px 10px;border:1px solid #ffd700;font-size:12px;font-weight:600;">' + sesion + '</td>' +
    '<td style="padding:8px 10px;border:1px solid #ffd700;font-size:12px;">' + empresa + '</td>' +
    '<td style="padding:8px 10px;border:1px solid #ffd700;font-size:12px;">' + punto + '</td>' +
    '<td style="padding:8px 10px;border:1px solid #ffd700;font-size:12px;white-space:nowrap;">' + cierreStr + '</td>' +
    '<td style="padding:8px 10px;border:1px solid #ffd700;font-size:12px;white-space:nowrap;color:#dc3545;font-weight:700;">' + modifStr + '</td>' +
    '<td style="padding:8px 10px;border:1px solid #ffd700;font-size:11px;color:#e67e00;">' + diffLabel + '</td>' +
    '<td style="padding:8px 10px;border:1px solid #ffd700;font-size:12px;text-align:right;">' + saldo + '</td>' +
    '<td style="padding:8px 10px;border:1px solid #ffd700;font-size:12px;text-align:right;' + diffStyle + '">' + diffText + '</td>' +
    '<td style="padding:8px 10px;border:1px solid #ffd700;font-size:12px;color:#555;">' + responsable + '</td>' +
    '</tr>';
});

var tabla = '<table style="width:100%;border-collapse:collapse;font-size:13px;">' +
  '<thead><tr style="background:#e67e00;color:#fff;">' +
  '<th style="padding:9px 10px;text-align:left;">Sesi\u00f3n</th>' +
  '<th style="padding:9px 10px;text-align:left;">Empresa</th>' +
  '<th style="padding:9px 10px;text-align:left;">Punto de Venta</th>' +
  '<th style="padding:9px 10px;text-align:left;">Fecha Cierre</th>' +
  '<th style="padding:9px 10px;text-align:left;">Fecha Modificaci\u00f3n</th>' +
  '<th style="padding:9px 10px;text-align:left;">Tiempo Despu\u00e9s</th>' +
  '<th style="padding:9px 10px;text-align:right;">Saldo Final</th>' +
  '<th style="padding:9px 10px;text-align:right;">Diferencia</th>' +
  '<th style="padding:9px 10px;text-align:left;">Modificado por</th>' +
  '</tr></thead>' +
  '<tbody>' + filas + '</tbody></table>';

return [{ json: {
  tabla: tabla,
  total: sospechosas.length,
  now_label: params.now_label
} }];
